#!/usr/bin/env python3
import sys,base64,zlib,hashlib
from pathlib import Path
r=Path(sys.argv[1]).resolve()
java=r/'app/src/main/java/de/deltaesc/tool'
tools=r/'tools'
base={'BleUartClient.java':'3bbf0a9e06dd277ef30cecae9baf579f8f843b0e5db505853cfe78c916b14485','NinebotCrypto.java':'57d88389891ad2fe5dc42dc69748c2a81dc24edc3930081a74ceee45ae035705','NinebotProtocol.java':'866fb803a439faf78ce50655cf54cae15a4467766826088e0bfa86b8468e84a3'}
for n,h in base.items():
    got=hashlib.sha256((java/n).read_bytes()).hexdigest()
    if got!=h: raise RuntimeError(f'frozen G30 transport changed: {n} {got}')
def put(path,data): path.write_bytes(zlib.decompress(base64.b64decode(data)))
put(java/'MainActivity.java','')
put(java/'MotorBenchProtocol.java','')
put(tools/'TestMotorBenchProtocol.java','')
assert hashlib.sha256((java/'MainActivity.java').read_bytes()).hexdigest()=='bf33628fc25d252449e1535e8c99d286cc1ae10fcc70b98bca10d6678f085292'
assert hashlib.sha256((java/'MotorBenchProtocol.java').read_bytes()).hexdigest()=='10916669485c560e214d9d72c8140f6bfeec01e860c31f5fcda945955e082471'
assert hashlib.sha256((tools/'TestMotorBenchProtocol.java').read_bytes()).hexdigest()=='c59be5046e5e1693129233b75fe7467e66058637075a593b7f396542ad9dc2ac'
mp=java/'MainActivity.java'
ms=mp.read_text()
old='case 0xD8:return 12;case 0xD9:return 8;default:return 16;'
new='case 0xD8:return 12;case 0xD9:return 12;default:return 16;'
if ms.count(old)!=1: raise RuntimeError('D9 length anchor mismatch')
mp.write_text(ms.replace(old,new,1))
assert hashlib.sha256(mp.read_bytes()).hexdigest()=='b4f99d25182bd2c35f15f610410d88f74987cfcc2531328001404c17895db424'
ms=mp.read_text()
old_stop='private void tryEmergencyStop(){if(stage!=4){stopWanted=false;benchState.setText("E6 nicht sendbar: nicht verbunden");return;}'
new_stop='private void tryEmergencyStop(){if(stage!=4||!deltaDetected){stopWanted=false;benchState.setText("E6 nicht sendbar: keine bestätigte DeltaESC-Signatur");return;}'
if ms.count(old_stop)!=1: raise RuntimeError('E6 signature gate anchor mismatch')
ms=ms.replace(old_stop,new_stop,1)
ms=ms.replace('/** G30 bench app: frozen BLE/NinebotCrypto transport, DeltaESC v0.7.3 bench control UI. */','/** G30 bench app: frozen BLE/NinebotCrypto transport, DeltaESC v0.7.6 time-boxed bench control UI. */')
mp.write_text(ms)
assert hashlib.sha256(mp.read_bytes()).hexdigest()=='84fe4e2f0ab7c54536f428014c6ef09a7e7a9799ec53991d041366a34710b5d3'
g=r/'app/build.gradle'
s=g.read_text().replace("applicationId 'de.deltaesc.motorprobe'","applicationId 'de.deltaesc.motorbench'").replace('versionCode 30','versionCode 31').replace("versionName '0.3.0'","versionName '0.3.1'")
g.write_text(s)
manifest=r/'app/src/main/AndroidManifest.xml'
manifest.write_text(manifest.read_text().replace('android:label="DashBLE Motor"','android:label="G30 Motor Bench"'))
for n,h in base.items():
    assert hashlib.sha256((java/n).read_bytes()).hexdigest()==h,n
main=(java/'MainActivity.java').read_text(); proto=(java/'MotorBenchProtocol.java').read_text()
assert 'BUILD_MOTOR_BENCH_TIMEOUT = 0x0760' in proto
assert 'handler.postDelayed(this::emergencyStop,1200)' in main
assert 'F0–F4 anwenden (nur RAM)' in main
assert '0xF5' not in main and 'IAP' not in main
print('v0.3.1 motor bench overlay PASS; frozen G30 transport unchanged')
